//! Port of symfony/string: ByteString, CodePointString and UnicodeString
//! with the AbstractString and AbstractUnicodeString behaviour they share,
//! the PHP functions they call, the `u()`, `b()` and `s()` helpers,
//! LazyString, and the English, French and Spanish inflectors.
//!
//! Upstream: symfony/string Resources/functions.php

#![forbid(unsafe_code)]

pub mod abstract_string;
pub mod abstract_unicode_string;
pub mod byte_string;
// generated by scripts/gen-string-tables.py, which --check compares byte for byte
#[rustfmt::skip]
mod case_tables;
pub mod code_point_string;
pub mod exception;
pub mod inflector;
pub mod intl;
pub mod lazy_string;
pub mod mb;
pub mod php;
pub mod preg;
mod tables;
pub mod unicode_string;

pub use abstract_string::{AbstractString, Needle, Replacement, TruncateMode, Wrapped};
pub use byte_string::ByteString;
pub use code_point_string::CodePointString;
pub use exception::{Error, InvalidArgumentException, RuntimeException};
pub use inflector::{EnglishInflector, FrenchInflector, Inflector, SpanishInflector};
pub use lazy_string::LazyString;
pub use unicode_string::UnicodeString;

/// `u($string)`.
pub fn u(string: &str) -> UnicodeString {
    UnicodeString::new(string)
}

/// `b($string)`.
pub fn b(string: impl AsRef<[u8]>) -> ByteString {
    ByteString::new(string)
}

/// `s($string)`: a UnicodeString for valid UTF-8, a ByteString otherwise.
pub fn s(string: impl AsRef<[u8]>) -> Str {
    match std::str::from_utf8(string.as_ref()) {
        Ok(text) => Str::Unicode(UnicodeString::new(text)),
        Err(_) => Str::Byte(ByteString::new(string)),
    }
}

/// What `s()` returns.
#[derive(Debug, Clone, PartialEq)]
pub enum Str {
    Unicode(UnicodeString),
    Byte(ByteString),
}
